(() => {
  'use strict';
  const charts=window.LightweightCharts;if(!charts?.createChart)return;const originalCreateChart=charts.createChart;const PAN_START_SLOP=7;
  function installPlotPan(chart){const canvas=chart?.canvas;if(!canvas||typeof chart.currentPriceRange!=='function'||typeof chart.visibleWindow!=='function')return;let gesture=null;
    function currentRange(){const w=chart.visibleWindow?.(),rows=w?.rows||[],fallback=rows.length?rows:(w?.all||[]).slice(-1),r=chart.currentPriceRange(fallback);if(!r||!(Number(r.span)>0))return null;return{min:Number(r.min),max:Number(r.max),span:Number(r.span)}}
    function start(event){if(chart.__galkaCrosshairLocked){gesture=null;return}if(event.pointerType==='mouse'&&event.button!==0)return;const g=chart.geometry?.(),rect=canvas.getBoundingClientRect(),x=event.clientX-rect.left,y=event.clientY-rect.top;if(!g||x<g.left||x>g.right||y<g.top||y>g.bottom){gesture=null;return}const range=currentRange();if(!range)return;gesture={pointerId:event.pointerId,startX:event.clientX,startY:event.clientY,range,mode:'pending'}}
    function move(event){if(chart.__galkaCrosshairLocked){gesture=null;return}if(!gesture||gesture.pointerId!==event.pointerId)return;if((chart.activePointers?.size||0)>=2){gesture=null;return}const dx=event.clientX-gesture.startX,dy=event.clientY-gesture.startY;if(gesture.mode==='pending'){if(Math.hypot(dx,dy)<PAN_START_SLOP)return;if(Math.abs(dy)>Math.abs(dx)*.85){gesture.mode='vertical';canvas.dispatchEvent(new CustomEvent('galka:native-plot-pan-start',{detail:{pointerId:event.pointerId}}))}else{gesture.mode='horizontal';return}}if(gesture.mode!=='vertical')return;event.preventDefault();event.stopImmediatePropagation();const g=chart.geometry?.(),height=Math.max(1,Number(g?.plotHeight||canvas.clientHeight||1)),shift=(dy/height)*gesture.range.span;chart.manualPriceRange={min:gesture.range.min+shift,max:gesture.range.max+shift,span:gesture.range.span};if(chart.gesture?.type==='pan')chart.gesture.moved=true;chart.crosshair=null;chart.draw?.()}
    function finish(event){if(gesture?.pointerId===event.pointerId)gesture=null}
    canvas.addEventListener('galka:crosshair-lock',event=>{if(event.detail?.locked)gesture=null});canvas.addEventListener('pointerdown',start,{capture:true,passive:true});canvas.addEventListener('pointermove',move,{capture:true,passive:false});canvas.addEventListener('pointerup',finish,{capture:true,passive:true});canvas.addEventListener('pointercancel',finish,{capture:true,passive:true});
  }
  window.LightweightCharts=Object.freeze({...charts,createChart(container,options){const chart=originalCreateChart(container,options);installPlotPan(chart);return chart}});
})();
